<template>
  <div class="tp-page">
    <t-card class="tp-card">
      <template #title>
        <div class="tp-head">
          <span class="tp-title">问题标签</span>
          <span class="tp-sub">
            共 {{ tags.length }} 个概念。括号里是同义词——搜索任一种说法都能找到同一批题，
            展示与筛选用的一律是括号前的通用名。
          </span>
        </div>
      </template>
      <t-loading :loading="loading">
        <div v-if="tags.length === 0" class="tp-empty">暂无标签</div>
        <t-space v-else break-line size="small">
          <t-button
            v-for="tag in tags"
            :key="tag.id"
            class="tp-tag"
            theme="default"
            variant="outline"
            :ghost="true"
            @click="goTag(tag)"
          >
            {{ tag.name }}
            <span v-if="tag.aliases && tag.aliases.length" class="tp-alias">
              （{{ tag.aliases.join(" / ") }}）
            </span>
          </t-button>
        </t-space>
      </t-loading>
    </t-card>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from "vue";
import { useRouter } from "vue-router";
import { GetProblemTagList } from "@/apis/problem.ts";

// 本地接口而不是复用 ProblemTag：别名是后端按需填充的字段（gorm:"-"），
// 只在这个页面用得到，不值得为它改动共享类型。
interface TagItem {
  id: number;
  name: string;
  aliases?: string[];
}

const tags = ref<TagItem[]>([]);
const loading = ref(false);
const router = useRouter();

const fetchTags = async () => {
  loading.value = true;
  try {
    // -1 = 全量。这个页面就是要展示全部概念，不做渲染裁剪
    const res = await GetProblemTagList(-1);
    if (res.code === 0) {
      tags.value = (res.data.list ?? []) as TagItem[];
    }
  } finally {
    loading.value = false;
  }
};

// 点标签 = 回题目列表按它筛题。传通用名而不是别名：SearchTagIds 第一步就查别名表，
// 用通用名或任一同义词的效果一致，而通用名在 URL 里更可读。
const goTag = (tag: TagItem) => {
  router.push({ name: "problem-list", query: { tag: tag.name } });
};

onMounted(fetchTags);
</script>

